struct Scope {
    private(set) var symbols: [String: Symbol] = [:]
    let parent: Scope?
    mutating func define(_ n: String, _ s: Symbol) -> Bool { symbols.updateValue(s, forKey: n) == nil }
    func lookup(_ name: String) -> Symbol? {            // innermost outward
        var scope: Scope? = self
        while let cur = scope {
            if let sym = cur.symbols[name] { return sym }
            scope = cur.parent
        }
        return nil
    }
}

